/**
 * ARCHIVO: 00_catalogo_indicadores_v1_sedatu.js
 * PROPÓSITO: Lote v1 de importación institucional del catálogo de
 *            indicadores de SEDATU — generado a partir del Excel oficial
 *            del programador del tablero de la secretaría
 *            (Variables_DGPDI_13052026.xlsx), hoja "Variables".
 *
 * Generado una sola vez con un script de conversión (no versionado en
 * el repo, igual que PROGRAMAS_RAMO15 en 00_programas.js) que agrupó
 * las 1987 filas del Excel por nombre de variable y aplicó las
 * reglas de mapeo documentadas en el plan de este módulo: unidad
 * (Número/Porcentaje mapean directo; Millones de pesos/Nombre quedan
 * como Numero + unidad_personalizada), area_sugerida agrega TODAS las
 * UR de cada nombre (no solo la primera), codigo_linea_accion se
 * extrae de la columna Resultado solo para PSEDATU, referencia (NO
 * fuente) guarda esa misma columna Resultado tal cual, y las 21
 * entradas con unidad original "Nombre" (cualitativas, no numéricas)
 * entran con activo=false — cola de revisión del admin, no aparecen en
 * el selector de usuarios.
 *
 * No editar este array a mano — si hace falta corregir una entrada ya
 * importada, hazlo desde el panel de administración (persiste en BD,
 * no en este archivo). Un Excel nuevo de otra dirección general es un
 * LOTE NUEVO (archivo 01_catalogo_indicadores_v2_*.js), no una edición
 * de este.
 */
